title: $:/plugins/huwiki/music/widgets/musescore.js
type: application/javascript
module-type: widget
\*/
(function(){
"use strict";
var Widget=require("$:/core/modules/widgets/widget.js").widget;
var I18n=require("$:/plugins/huwiki/music/i18n.js");

// Only the official MuseScore score pages and their embed variants are permitted.
// Never load arbitrary markup or a URL constructed from an untrusted host.
function normaliseMuseScore(input){
  input=String(input||'').trim();
  // MuseScore's Share > Embed dialog provides an iframe. Allow pasting that too.
  var match=input.match(/<iframe\b[^>]*\bsrc\s*=\s*(["'])([^"']+)\1/i);
  if(match) input=match[2].replace(/&amp;/gi,'&');
  var u;
  // TiddlyWiki also renders with a Node sandbox that does not expose URL.
  var URLClass=typeof URL==='function'?URL:(typeof $tw!=='undefined'&&$tw.node?require('url').URL:null);
  try{u=new URLClass(input);}catch(e){return null;}
  if(u.protocol!=="https:" || !/^(?:www\.)?musescore\.com$/i.test(u.hostname) || u.username || u.password || u.port) return null;
  var path=u.pathname.replace(/\/+$/,"");
  if(!/^\/(?:user\/[^/]+\/)?scores\/\d+(?:\/s\/[A-Za-z0-9_-]+)?(?:\/embed)?$/i.test(path)) return null;
  path=path.replace(/\/embed$/i,"");
  var origin="https://musescore.com";
  return {score:origin+path+u.search,embed:origin+path+"/embed"+u.search};
}
function node(doc,tag,klass,text){
  var el=doc.createElement(tag);
  if(klass) el.className=klass;
  if(text) el.textContent=text;
  return el;
}
function MuseScoreWidget(parseTreeNode,options){this.initialise(parseTreeNode,options);}
MuseScoreWidget.prototype=new Widget();
MuseScoreWidget.prototype.execute=function(){
  this.sourceTiddler=this.getAttribute('tiddler',this.getVariable('currentTiddler',''));
  var fields=this.sourceTiddler&&this.wiki.getTiddler(this.sourceTiddler);
  this.url=this.getAttribute('url','')||(fields&&fields.fields['musescore-url'])||'';
  this.label=this.getAttribute('label','Vis og afspil noder');
  var h=parseInt(this.getAttribute('height','450'),10);
  this.height=String(Number.isFinite(h)?Math.min(1100,Math.max(260,h)):450);
};
MuseScoreWidget.prototype.render=function(parent,nextSibling){
  this.parentDomNode=parent;
  this.computeAttributes();this.execute();
  var doc=this.document,host=node(doc,'section','huw-musecore-widget');
  parent.insertBefore(host,nextSibling);
  this.domNodes.push(host);this._localeObserver=I18n.observe(host,this.wiki);
  var info=normaliseMuseScore(this.url);
  if(!info){
    host.appendChild(node(doc,'p','huw-musecore-instruction',this.url?'Ugyldigt MuseScore-link. Brug et scorelink fra musescore.com eller indsæt den officielle indlejringskode.':'Indsæt et MuseScore-link i feltet ovenfor for at vise partitur og afspiller.'));
    this._localeObserver.refresh();
    return;
  }
  var bar=node(doc,'div','huw-musecore-toolbar'),play=node(doc,'button','huw-musecore-play',this.label);
  play.setAttribute('type','button');
  play.setAttribute('aria-expanded','false');
  bar.appendChild(play);
  var link=node(doc,'a','huw-musecore-link','Åbn direkte på MuseScore ↗');
  link.setAttribute('href',info.score);link.setAttribute('target','_blank');link.setAttribute('rel','noopener noreferrer');
  bar.appendChild(link);host.appendChild(bar);
  var screen=node(doc,'div','huw-musecore-screen');host.appendChild(screen);
  var note=node(doc,'p','huw-musecore-note','Tryk på ▶ i MuseScore-afspilleren for at høre melodien. Hvis partituret ikke vises, kan du åbne det direkte på MuseScore.');
  host.appendChild(note);
  play.addEventListener('click',function(){
    if(screen.firstChild){screen.textContent='';play.textContent=this.label;play.setAttribute('aria-expanded','false');return;}
    var iframe=node(doc,'iframe','huw-musecore-frame');
    iframe.setAttribute('title','MuseScore – partitur og afspiller');
    iframe.setAttribute('allow','autoplay; fullscreen');
    iframe.setAttribute('allowfullscreen','');
    iframe.setAttribute('referrerpolicy','strict-origin-when-cross-origin');
    iframe.setAttribute('loading','lazy');
    iframe.style.height=this.height+'px';
    iframe.src=info.embed;
    screen.appendChild(iframe);
    play.textContent='Skjul afspiller';
    play.setAttribute('aria-expanded','true');
  }.bind(this));
  this._localeObserver.refresh();
};
MuseScoreWidget.prototype.onDestroy=function(){if(this._localeObserver){this._localeObserver.destroy();this._localeObserver=null;}};
MuseScoreWidget.prototype.refresh=function(changedTiddlers){
  var attrs=this.computeAttributes();
  if(attrs.tiddler||attrs.url||attrs.height||attrs.label||(this.sourceTiddler&&changedTiddlers[this.sourceTiddler])){
    this.refreshSelf();return true;
  }
  return this.refreshChildren(changedTiddlers);
};
exports.musescore=MuseScoreWidget;
exports.normaliseMuseScore=normaliseMuseScore;
})();
