'use strict';
const Widget=require('$:/core/modules/widgets/widget.js').widget;
const I18n=require('$:/plugins/huwiki/music/i18n.js');
const data=require('$:/plugins/huwiki/music/data.js');
function el(doc,tag,cls,text){const n=doc.createElement(tag);if(cls)n.className=cls;if(text!==undefined)n.textContent=text;return n;}
function button(doc,parent,text,action,cls){const n=el(doc,'button',cls||'huw-music-button',text);n.setAttribute('type','button');n.addEventListener('click',action);parent.appendChild(n);return n;}
function input(doc,parent,label,value,options={}){
 const wrap=el(doc,'label','huw-music-input');wrap.appendChild(el(doc,'span','',label));
 const n=el(doc,options.multiline?'textarea':'input');n.value=String(value==null?'':value);if(options.multiline)n.setAttribute('rows',options.rows||3);
 else n.setAttribute('type',options.type||'text');if(options.placeholder)n.setAttribute('placeholder',options.placeholder);
 n.setAttribute('aria-label',label);wrap.appendChild(n);parent.appendChild(wrap);return n;
}
function save(widget,fields){
 const existing=widget.wiki.getTiddler(widget.source);if(!existing)throw Error('Tiddleren findes ikke længere.');
 widget.wiki.addTiddler(new $tw.Tiddler(existing,widget.wiki.getModificationFields(),fields));
}
function saveTag(widget,tag,fields){
 const old=widget.wiki.getTiddler(widget.source),tags=old.fields.tags||[];
 save(widget,Object.assign({tags:[...new Set(tags.concat(['Musik',tag]))]},fields));
}
function svg(doc,parent,markup,cls){const n=el(doc,'div',cls);n.innerHTML=markup;parent.appendChild(n);return n;}
function svgLink(doc,parent,markup,title){const a=el(doc,'a','huw-music-download','Hent diagram som SVG');a.setAttribute('href','data:image/svg+xml;charset=utf-8,'+encodeURIComponent(markup));a.setAttribute('download',String(title||'Musik').replace(/[\\/:*?"<>|]/g,'-')+'.svg');parent.appendChild(a);}
function Music(parseTreeNode,options){this.initialise(parseTreeNode,options);}
Music.prototype=new Widget();
Music.prototype.execute=function(){this.source=this.getAttribute('tiddler',this.getVariable('currentTiddler',''));this.kind=this.getAttribute('kind','');};
Music.prototype.render=function(parent,next){
 this.parentDomNode=parent;this.computeAttributes();this.execute();
 const host=el(this.document,'div','huw-music-component');parent.insertBefore(host,next);this.domNodes.push(host);
 this.host=host;this._localeObserver=I18n.observe(host,this.wiki);this.fields=(this.wiki.getTiddler(this.source)||{fields:{title:this.source}}).fields;
 try{this.draw(host);}catch(error){host.appendChild(el(this.document,'p','huw-music-error',error.message||String(error)));}
 this._localeObserver.refresh();
};
Music.prototype.onDestroy=function(){if(this._localeObserver){this._localeObserver.destroy();this._localeObserver=null;}};
Music.prototype.refresh=function(changed){const attrs=this.computeAttributes();if(Object.keys(attrs).length||changed['$:/language']||changed[this.source]){this.refreshSelf();return true;}return this.refreshChildren(changed);};

function Chord(tree,options){this.initialise(tree,options);}Chord.prototype=new Music();
Chord.prototype.draw=function(host){const markup=data.chordSvg(this.fields);svg(this.document,host,markup,'huw-music-chord');if(this.getAttribute('download','yes')!=='no')svgLink(this.document,host,markup,this.fields['guitar-chord-name']||this.source);};
function Tab(tree,options){this.initialise(tree,options);}Tab.prototype=new Music();
Tab.prototype.draw=function(host){const d=data.readTab(this.fields['guitar-tab']),markup=data.tabSvg(d,this.source);const canvas=svg(this.document,host,markup,'huw-music-tab');canvas.style.minWidth=Math.max(420,100+d.rows[0].length*48)+'px';host.className+=' huw-music-tab-scroll';};

function ChordEditor(tree,options){this.initialise(tree,options);}ChordEditor.prototype=new Music();
ChordEditor.prototype.draw=function(host){
 const doc=this.document,details=el(doc,'details','huw-music-editor');details.appendChild(el(doc,'summary','','Ret akkorddiagrammet'));host.appendChild(details);
 const box=el(doc,'div','huw-music-form');details.appendChild(box);
 const name=input(doc,box,'Akkordens navn',this.fields['guitar-chord-name']||this.source);
 const presetWrap=el(doc,'label','huw-music-input');presetWrap.appendChild(el(doc,'span','','Begynd med en kendt akkord'));
 const presets=el(doc,'select');const placeholder=el(doc,'option','','Vælg akkord');placeholder.value='';presets.appendChild(placeholder);
 Object.keys(data.presets).forEach(key=>{const o=el(doc,'option','',key);o.value=key;presets.appendChild(o);});presetWrap.appendChild(presets);box.appendChild(presetWrap);
 const frets=input(doc,box,'Bånd · dyb E → lys e',this.fields['guitar-frets']||'x 3 2 0 1 0',{placeholder:'x 3 2 0 1 0'});
 const fingers=input(doc,box,'Fingre · 0, 1–4 eller T',this.fields['guitar-fingers']||'0 0 0 0 0 0');
 const base=input(doc,box,'Første bånd · tomt felt vælger automatisk',this.fields['guitar-base-fret']||'',{type:'number'});
 const barres=input(doc,box,'Barré · fx 1:1-6',this.fields['guitar-barres']||'');
 box.appendChild(el(doc,'p','huw-music-hint','x = strengen spilles ikke. 0 = løs streng. Fingersætning er valgfri. Barré angives med bånd og strengnumre.'));
 presets.addEventListener('change',()=>{const p=data.presets[presets.value];if(!p)return;name.value=presets.value;frets.value=p.frets;fingers.value=p.fingers;base.value='';barres.value=p.barres||'';});
 const status=el(doc,'p','huw-music-status');status.setAttribute('role','status');
 button(doc,box,'Gem diagram',()=>{try{const f={'guitar-chord-name':name.value.trim()||this.source,'guitar-frets':frets.value.trim(),'guitar-fingers':fingers.value.trim(),'guitar-base-fret':base.value.trim(),'guitar-barres':barres.value.trim()};data.chord(f);saveTag(this,'Akkorddiagram',f);status.textContent='Diagrammet er gemt.';}catch(e){status.textContent=e.message;}});box.appendChild(status);
};

function TabEditor(tree,options){this.initialise(tree,options);}TabEditor.prototype=new Music();
TabEditor.prototype.draw=function(host){
 const doc=this.document,details=el(doc,'details','huw-music-editor');details.appendChild(el(doc,'summary','','Ret guitartabben'));host.appendChild(details);
 const box=el(doc,'div','huw-music-form');details.appendChild(box);let d;
 try{d=data.readTab(this.fields['guitar-tab']);}catch(e){box.appendChild(el(doc,'p','huw-music-error',e.message));return;}
 box.appendChild(el(doc,'p','huw-music-hint','Lys e øverst, dyb E nederst. Hver kolonne er en position; toner i samme kolonne spilles sammen. Brug 0–24, x eller fx 3h5 og 5p3.'));
 const grid=el(doc,'div','huw-music-tab-grid'),controls=el(doc,'div','huw-music-actions'),status=el(doc,'p','huw-music-status');status.setAttribute('role','status');box.appendChild(grid);box.appendChild(controls);let cells=[];
 const capture=()=>({version:1,rows:cells.map(r=>r.map(n=>data.token(n.value)))});
 const draw=()=>{
  grid.textContent='';cells=[];const table=el(doc,'table');
  const head=el(doc,'tr');head.appendChild(el(doc,'th','','Streng'));d.rows[0].forEach((_,i)=>head.appendChild(el(doc,'th','',String(i+1))));table.appendChild(head);
  d.rows.forEach((row,i)=>{const tr=el(doc,'tr');tr.appendChild(el(doc,'th','',['e',I18n.language(this.wiki)==='da'?'H':'B','G','D','A','E'][i]));const inputs=[];row.forEach((value,j)=>{const td=el(doc,'td'),n=el(doc,'input');n.value=value;n.setAttribute('aria-label',['e',I18n.language(this.wiki)==='da'?'H':'B','G','D','A','E'][i]+' – position '+(j+1));n.setAttribute('maxlength','12');n.setAttribute('autocomplete','off');td.appendChild(n);tr.appendChild(td);inputs.push(n);});cells.push(inputs);table.appendChild(tr);});grid.appendChild(table);
 };
 draw();
 button(doc,controls,'+ Position',()=>{try{d=capture();if(d.rows[0].length>=64)throw Error('Der kan være højst 64 positioner.');d.rows.forEach(r=>r.push(''));draw();status.textContent='';}catch(e){status.textContent=e.message;}});
 button(doc,controls,'Fjern sidste position',()=>{try{d=capture();if(d.rows[0].length===1)throw Error('Behold mindst én position.');if(d.rows.some(r=>r[r.length-1]!=='')){status.textContent='Tøm den sidste position, før du fjerner den.';return;}d.rows.forEach(r=>r.pop());draw();status.textContent='';}catch(e){status.textContent=e.message;}},'huw-music-button huw-music-button-secondary');
 button(doc,controls,'Gem tab',()=>{try{d=capture();saveTag(this,'Guitartab',{'guitar-tab':JSON.stringify(d)});status.textContent='Tabben er gemt.';}catch(e){status.textContent=e.message;}});
 button(doc,controls,'Kopiér som tekst',()=>{try{const text=data.tabText(capture());this.dispatchEvent({type:'tm-copy-to-clipboard',param:text});status.textContent='Tabben er kopieret.';}catch(e){status.textContent=e.message;}},'huw-music-button huw-music-button-secondary');
 const imported=input(doc,box,'Indsæt en eksisterende tab · seks linjer', '',{multiline:true,rows:6,placeholder:'e|--0--1--3--|\nB|-----------|\nG|-----------|\nD|-----------|\nA|-----------|\nE|-----------|'});
 button(doc,box,'Indlæs tab i felterne',()=>{try{if(cells.some(r=>r.some(n=>n.value!==''))){status.textContent='Tøm felterne først, så din nuværende tab ikke bliver overskrevet.';return;}d=data.importTab(imported.value);draw();status.textContent='Tabben er indlæst. Tryk Gem tab, når du er klar.';}catch(e){status.textContent=e.message;}},'huw-music-button huw-music-button-secondary');box.appendChild(status);
};

function Musikipedia(tree,options){this.initialise(tree,options);}Musikipedia.prototype=new Music();
Musikipedia.prototype.draw=function(host){
 const doc=this.document,url=data.normaliseMusikipedia(this.getAttribute('url','')||this.fields['musikipedia-url']);
 if(!url){host.appendChild(el(doc,'p','huw-music-hint',this.fields['musikipedia-url']?'Brug et HTTPS-link til en side eller øvelse på musikipedia.dk.':'Indsæt et link til en Musikipedia-side i feltet ovenfor.'));return;}
 const bar=el(doc,'div','huw-music-actions'),screen=el(doc,'div','huw-music-site-screen');host.appendChild(bar);host.appendChild(screen);
 const b=button(doc,bar,'Åbn øvelsen her',()=>{
  if(screen.firstChild){screen.textContent='';b.textContent='Åbn øvelsen her';b.setAttribute('aria-expanded','false');return;}
  const f=el(doc,'iframe','huw-music-site-frame');f.setAttribute('title','Musikipedia – '+this.source);f.setAttribute('allow','autoplay; fullscreen');f.setAttribute('allowfullscreen','');f.setAttribute('loading','lazy');f.setAttribute('src',url);screen.appendChild(f);b.textContent='Skjul øvelsen';b.setAttribute('aria-expanded','true');
 });b.setAttribute('aria-expanded','false');
 const a=el(doc,'a','huw-music-external','Åbn på Musikipedia ↗');a.setAttribute('href',url);a.setAttribute('target','_blank');a.setAttribute('rel','noopener noreferrer');bar.appendChild(a);
 host.appendChild(el(doc,'p','huw-music-hint','Dine øvelsesresultater og dit login hører til Musikipedia. Egne mål, status og noter gemmes her i wikien. Brug linket, hvis login eller øvelsen kræver en separat fane.'));
};

function create(widget,kind,url){
 // Resolve creation defaults when clicked. Keep these out of the UI dictionary:
 // personal titles and notes must remain unchanged when the language changes.
 const defaults=I18n.language(widget.wiki)==='da'?{
  titles:{abc:'Nyt nodeark',musescore:'Nyt partitur',chord:'Ny akkord',tab:'Ny guitartab',musikipedia:'Ny musikøvelse'},
  text:'!! Mit mål\n\nSkriv, hvad du vil øve.\n\n!! Noter og opgaver\n\nTilføj dine egne noter, øvetrin eller en opgave her.\n'
 }:{
  titles:{abc:'New score',musescore:'New score',chord:'New chord',tab:'New guitar TAB',musikipedia:'New music exercise'},
  text:'!! My goal\n\nWrite what you would like to practise.\n\n!! Notes and tasks\n\nAdd your own notes, practice steps or a task here.\n'
 };
 const title=widget.wiki.generateNewTitle(defaults.titles[kind]),fields={title,type:'text/vnd.tiddlywiki',tags:['Musik',data.labels[kind]],'musik-status':'Ny',text:defaults.text};
 if(kind==='abc'){fields.tags.push('ABC');fields['abc-source']='X:1\nT:'+title+'\nR:Jazz\nM:4/4\nL:1/8\nQ:1/4=120\nK:C\n"Dm7"D2 F2 A2 c2 | "G7"B2 A2 G2 F2 | "Cmaj7"E2 G2 c4 |]';fields['abc-layout']='jazz';fields['abc-accompaniment']=JSON.stringify({enabled:true,style:'auto',melodyVolume:100,bassVolume:65,chordVolume:48,drumVolume:35});}
 if(kind==='musescore')fields['musescore-url']='';
 if(kind==='chord')Object.assign(fields,{'guitar-chord-name':'C','guitar-frets':data.presets.C.frets,'guitar-fingers':data.presets.C.fingers});
 if(kind==='tab')fields['guitar-tab']=JSON.stringify(data.blankTab());
 if(kind==='musikipedia')fields['musikipedia-url']=url||'';
 widget.wiki.addTiddler(new $tw.Tiddler(widget.wiki.getCreationFields(),fields));
 widget.dispatchEvent({type:'tm-navigate',navigateTo:title,navigateFromTitle:widget.source,navigateFromNode:widget,navigateSuppressNavigation:false});return title;
}
function NewMusic(tree,options){this.initialise(tree,options);}NewMusic.prototype=new Music();
NewMusic.prototype.draw=function(host){
 const actions=el(this.document,'div','huw-music-new');host.appendChild(actions);
 const types=this.kind?[this.kind]:Object.keys(data.labels);
 types.forEach(k=>{button(this.document,actions,'+ '+data.labels[k],()=>create(this,k), 'huw-music-button huw-music-new-'+k);});
};

function Table(tree,options){this.initialise(tree,options);}Table.prototype=new Music();
Table.prototype.draw=function(host){
 const doc=this.document,controls=el(doc,'div','huw-music-table-controls'),search=el(doc,'input');search.value=this.query||'';search.setAttribute('type','search');search.setAttribute('placeholder','Find en melodi, akkord eller øvelse…');search.setAttribute('aria-label','Søg i musikbiblioteket');controls.appendChild(search);
 const filters=el(doc,'div','huw-music-tabs');controls.appendChild(filters);host.appendChild(controls);
 const summary=el(doc,'p','huw-music-hint'),screen=el(doc,'div','huw-music-table-scroll');host.appendChild(summary);host.appendChild(screen);let active=this.active||this.kind||'';const buttons=[];
 ['',...Object.keys(data.labels)].forEach(k=>{const b=button(doc,filters,k?data.labels[k]:'Alt',()=>{active=k;draw();},'huw-music-filter');buttons.push([k,b]);});
 const draw=()=>{
  this.query=search.value;this.active=active;screen.textContent='';const all=data.list(this.wiki),q=search.value.trim().toLocaleLowerCase('da');const rows=all.filter(r=>(!active||r.types.includes(active))&&(!q||[r.title,...(r.fields.tags||[]),r.fields['musik-status']||''].join(' ').toLocaleLowerCase('da').includes(q)));
  buttons.forEach(([k,b])=>{b.setAttribute('aria-pressed',String(k===active));});summary.textContent=(I18n.language(this.wiki)==='da'?rows.length+' af '+all.length+' tiddlere · én række pr. tiddler':rows.length+' of '+all.length+' tiddlers · one row per tiddler');
  if(!rows.length){screen.appendChild(el(doc,'p','huw-music-empty','Her vises dine ABC-nodeark, partiturer, akkorddiagrammer, tabs og øvelser. Opret den første med knapperne ovenfor.'));return;}
  const table=el(doc,'table','huw-music-table'),head=el(doc,'thead'),hrow=el(doc,'tr');['Titel','Indhold','Status','Ændret'].forEach(s=>hrow.appendChild(el(doc,'th','',s)));head.appendChild(hrow);table.appendChild(head);const body=el(doc,'tbody');table.appendChild(body);
  const counts=new Map(),scoreFor=r=>{const f=r.fields,normalise=require('$:/plugins/huwiki/music/widgets/musescore.js').normaliseMuseScore;const s=normalise(f['musescore-url']);return s&&s.score;};
  all.forEach(r=>{const s=scoreFor(r);if(s)counts.set(s,(counts.get(s)||0)+1);});
  rows.forEach(r=>{
   const tr=el(doc,'tr','huw-music-row-'+r.types[0]),name=el(doc,'td'),link=el(doc,'a','huw-music-title',(I18n.language(this.wiki)==='da'?r.fields['huwiki-title-da']:r.fields['huwiki-title-en'])||r.title);link.setAttribute('href','#'+encodeURIComponent(r.title));link.addEventListener('click',e=>{e.preventDefault();this.dispatchEvent({type:'tm-navigate',navigateTo:r.title,navigateFromTitle:this.source,navigateFromNode:this});});name.appendChild(link);
   if(counts.get(scoreFor(r))>1)name.appendChild(el(doc,'small','huw-music-shared','Samme partitur · '+counts.get(scoreFor(r))+' noter'));tr.appendChild(name);
   const types=el(doc,'td');r.types.forEach(k=>types.appendChild(el(doc,'span','huw-music-chip huw-music-chip-'+k,data.labels[k])));tr.appendChild(types);
   tr.appendChild(el(doc,'td','',r.fields['musik-status']||'Ny'));const date=String(r.fields.modified||''),day=/^\d{8}/.test(date)?date.slice(6,8)+'.'+date.slice(4,6)+'.'+date.slice(0,4):'—';tr.appendChild(el(doc,'td','',day));body.appendChild(tr);
  });screen.appendChild(table);
 };search.addEventListener('input',draw);draw();
};
