var translatePrefixes=Object.keys(translations).filter(function(k){return k.endsWith(':');}).sort(function(a,b){return b.length-a.length;});
function language(wiki){
 var value='';
 if(wiki&&typeof wiki.getTiddlerText==='function')value=wiki.getTiddlerText('$:/language','')||'';
 else if(typeof window!=='undefined')value=window.HUWMusicSiteLanguage||document.documentElement.lang||'';
 var wantsDanish=/(?:\/|^|\b)da(?:[-_]|$)/i.test(value);
 if(!wantsDanish)return 'en';
 if(wiki&&typeof wiki.getTiddler==='function'){
  var langPlugin=wiki.getTiddler(value);
  return langPlugin&&langPlugin.fields&&langPlugin.fields['plugin-type']==='language'?'da':'en';
 }
 // The exported Site has no TiddlyWiki runtime or core language plugin.
 return 'da';
}
function translate(value,lang){
 var raw=String(value==null?'':value);
 if((lang||'da')==='da')return raw;
 var core=raw.trim();if(!core)return raw;
 var replacement=translations[core];
 if(replacement===undefined){
  for(var i=0;i<translatePrefixes.length;i++){
   var prefix=translatePrefixes[i];
   if(core.indexOf(prefix)===0){replacement=translations[prefix]+core.slice(prefix.length);break;}
  }
 }
 if(replacement===undefined)return raw;
 return raw.replace(core,replacement);
}
function noteName(midi,system,sharp){
 var values=sharp?['C','C♯','D','D♯','E','F','F♯','G','G♯','A','A♯','B']:
 ['C','D♭','D','E♭','E','F','G♭','G','A♭','A','B♭','B'];
 var name=values[((midi%12)+12)%12];
 return system==='da'?name.replace(/^B$/, 'H').replace(/^B♭$/, 'B'):name;
}
function observe(root,wiki){
 if(!root)return {refresh:function(){},destroy:function(){}};
 // Native static exports use TiddlyWiki's fake DOM, not browser Nodes.
 if(root.isTiddlyWikiFakeDom){
  function refreshStatic(){
   var lang=language(wiki);
   function visit(node){
    if(node.nodeType===3){node.textContent=translate(node.textContent,lang);return;}
    if(node.nodeType!==1)return;
    if(/^(script|style|svg|textarea|pre|code)$/i.test(node.tagName)||node.getAttribute('contenteditable')==='true'||/(^|\s)(huwabc-paper|huwabc-edit-preview|huwabc-readable-abc|huwabc-code|huw-music-tab-grid)(\s|$)/.test(node.className))return;
    ['aria-label','title','placeholder'].forEach(function(key){var value=node.getAttribute(key);if(value!==undefined&&value!==null)node.setAttribute(key,translate(value,lang));});
    node.childNodes.forEach(visit);
   }
   visit(root);
  }
  refreshStatic();
  return {refresh:refreshStatic,destroy:function(){}};
 }
 var texts=new WeakMap(),attributes=new WeakMap(),closed=false;
 function allowed(node){
  var element=node.nodeType===1?node:node.parentElement;
  if(!element)return false;
  if(element.closest('script,style,svg,textarea,pre,code,[contenteditable="true"],.huwabc-paper,.huwabc-edit-preview,.huwabc-readable-abc,.huwabc-code,.huw-music-tab-grid'))return false;
  // Treat musical notation, external source excerpts and user input as data, not UI.
  return true;
 }
 function setText(node,lang){
  if(!allowed(node))return;
  var old=texts.get(node),now=node.nodeValue;
  if(old===undefined||now!==old&&now!==translate(old,'en')){old=now;texts.set(node,old);}
  var next=translate(old,lang);if(now!==next)node.nodeValue=next;
 }
 function setAttrs(node,lang){
  if(!allowed(node))return;
  var originals=attributes.get(node)||{};
  ['aria-label','title','placeholder'].forEach(function(key){
   if(!node.hasAttribute||!node.hasAttribute(key))return;
   var now=node.getAttribute(key),old=originals[key];
   if(old===undefined||now!==old&&now!==translate(old,'en'))old=now;
   originals[key]=old;
   var next=translate(old,lang);if(now!==next)node.setAttribute(key,next);
  });
  attributes.set(node,originals);
 }
 function walk(start,lang){
  if(!start)return;
  if(start.nodeType===3){setText(start,lang);return;}
  if(start.nodeType!==1&&start.nodeType!==9&&start.nodeType!==11)return;
  if(start.nodeType===1){if(!allowed(start))return;setAttrs(start,lang);}
  var walker=(start.ownerDocument||document).createTreeWalker(start,NodeFilter.SHOW_TEXT|NodeFilter.SHOW_ELEMENT);
  var node;while((node=walker.nextNode())){
   if(node.nodeType===3)setText(node,lang);
   else if(node.nodeType===1)setAttrs(node,lang);
  }
 }
 function refresh(){if(!closed)walk(root,language(wiki));}
 var obs=typeof MutationObserver==='function'?new MutationObserver(function(records){
  if(closed)return;
  var lang=language(wiki);
  records.forEach(function(record){
   if(record.type==='characterData')walk(record.target,lang);
   else if(record.type==='attributes')setAttrs(record.target,lang);
   else if(record.type==='childList')record.addedNodes.forEach(function(n){walk(n,lang);});
  });
 }):null;
 if(obs)obs.observe(root,{subtree:true,childList:true,characterData:true,attributes:true,attributeFilter:['aria-label','title','placeholder']});
 function changed(changes){if(changes&&changes['$:/language'])refresh();}
 if(wiki&&wiki.addEventListener)wiki.addEventListener('change',changed);
 refresh();
 return {refresh:refresh,destroy:function(){closed=true;if(obs)obs.disconnect();if(wiki&&wiki.removeEventListener)wiki.removeEventListener('change',changed);}};
}
exports.language=language;
exports.translate=translate;
exports.noteName=noteName;
exports.observe=observe;
exports.dictionary=translations;
})();
